"""rd_lib: finite fields F_{p^k}, univariate polynomials, elliptic-curve group
law, Semaev S_3 and resultant-built fibres S_{n+1}(x_1..x_n, T).

Written from scratch for blind re-derivation TASK-20261029-3ac467.
Pure Python 3 (no third-party library). Nothing here is imported from the
repository.
"""
import itertools
import math
import random


# ---------------------------------------------------------------- fields

def _prime_factors(n):
    fs, d = [], 2
    while d * d <= n:
        if n % d == 0:
            fs.append(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        fs.append(n)
    return fs


class Field:
    """F_Q with Q = p^k.  Elements are ints in [0, Q): the int sum c_i p^i
    encodes sum c_i z^i in F_p[z]/(m(z)), m a primitive polynomial, so z
    generates F_Q^*.  F_p is the set of ints 0..p-1 inside F_Q."""

    def __init__(self, p, k=1):
        self.p, self.k = p, k
        self.Q = Q = p ** k
        self.exp = [0] * (2 * (Q - 1))
        self.log = [None] * Q
        if k == 1:
            g = self._gen_prime(p)
            x = 1
            for i in range(Q - 1):
                self.exp[i] = x
                self.log[x] = i
                x = x * g % p
            self.modpoly = None
            self.gen = g
        else:
            self.modpoly = self._primitive_poly(p, k)
            digs = [1] + [0] * (k - 1)
            for i in range(Q - 1):
                v = self._enc(digs)
                self.exp[i] = v
                self.log[v] = i
                digs = self._times_z(digs)
            self.gen = p  # the encoding of z
            # Zech table: zech[d] = log(1 + g^d), or -1 if 1 + g^d == 0
            self.zech = [0] * (Q - 1)
            for d in range(Q - 1):
                dg = self._dec(self.exp[d])
                dg[0] = (dg[0] + 1) % p
                v = self._enc(dg)
                self.zech[d] = -1 if v == 0 else self.log[v]
        for i in range(Q - 1, 2 * (Q - 1)):
            self.exp[i] = self.exp[i - (Q - 1)]
        self.half = (Q - 1) // 2

    # --- construction helpers
    @staticmethod
    def _gen_prime(p):
        fs = _prime_factors(p - 1)
        for g in range(2, p):
            if all(pow(g, (p - 1) // r, p) != 1 for r in fs):
                return g
        raise ValueError

    def _enc(self, digs):
        v = 0
        for c in reversed(digs):
            v = v * self.p + c
        return v

    def _dec(self, v):
        out = []
        for _ in range(self.k):
            v, c = divmod(v, self.p)
            out.append(c)
        return out

    def _times_z(self, digs, m=None):
        m = self.modpoly if m is None else m
        p, k = self.p, self.k
        top = digs[-1]
        new = [0] + digs[:-1]
        if top:
            # z^k = -(m_0 + m_1 z + ... + m_{k-1} z^{k-1})
            new = [(new[i] - top * m[i]) % p for i in range(k)]
        return new

    def _primitive_poly(self, p, k):
        Q = p ** k
        for coeffs in itertools.product(range(p), repeat=k):
            m = list(coeffs)  # m_0..m_{k-1}; monic of degree k
            if m[0] == 0:
                continue
            digs = [1] + [0] * (k - 1)
            order = None
            for i in range(1, Q):
                digs = self._times_z(digs, m)
                if digs == [1] + [0] * (k - 1):
                    order = i
                    break
            if order == Q - 1:
                return m
        raise ValueError("no primitive polynomial")

    # --- arithmetic
    def add(self, a, b):
        if self.k == 1:
            return (a + b) % self.p
        if a == 0:
            return b
        if b == 0:
            return a
        la = self.log[a]
        d = self.log[b] - la
        if d < 0:
            d += self.Q - 1
        z = self.zech[d]
        if z < 0:
            return 0
        return self.exp[la + z]

    def neg(self, a):
        if self.k == 1:
            return (-a) % self.p
        if a == 0:
            return 0
        return self.exp[self.log[a] + self.half]

    def sub(self, a, b):
        return self.add(a, self.neg(b))

    def mul(self, a, b):
        if self.k == 1:
            return a * b % self.p
        if a == 0 or b == 0:
            return 0
        return self.exp[self.log[a] + self.log[b]]

    def inv(self, a):
        if a == 0:
            raise ZeroDivisionError
        if self.k == 1:
            return pow(a, self.p - 2, self.p)
        return self.exp[(self.Q - 1 - self.log[a]) % (self.Q - 1)]

    def div(self, a, b):
        return self.mul(a, self.inv(b))

    def pw(self, a, e):
        if e == 0:
            return 1
        if a == 0:
            return 0
        return self.exp[(self.log[a] * e) % (self.Q - 1)]

    def chi(self, a):
        if a == 0:
            return 0
        return 1 if self.log[a] % 2 == 0 else -1

    def sqrt(self, a):
        if a == 0:
            return 0
        la = self.log[a]
        if la % 2:
            return None
        return self.exp[la // 2]

    def c(self, n):
        """image of the integer n in F_Q"""
        return n % self.p

    def frob(self, a):
        return self.pw(a, self.p)

    def in_prime_field(self, a):
        return a < self.p

    def elements(self):
        return range(self.Q)

    def rand(self, rng):
        return rng.randrange(self.Q)


# ---------------------------------------------------------------- polynomials
# lists low -> high, trimmed; zero polynomial = []

def ptrim(a):
    while a and a[-1] == 0:
        a.pop()
    return a


def pdeg(a):
    return len(a) - 1


def padd(F, a, b):
    n = max(len(a), len(b))
    out = []
    for i in range(n):
        x = a[i] if i < len(a) else 0
        y = b[i] if i < len(b) else 0
        out.append(F.add(x, y))
    return ptrim(out)


def pneg(F, a):
    return [F.neg(x) for x in a]


def psub(F, a, b):
    return padd(F, a, pneg(F, b))


def pscale(F, a, c):
    return ptrim([F.mul(x, c) for x in a])


def pmul(F, a, b):
    if not a or not b:
        return []
    out = [0] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        if x == 0:
            continue
        for j, y in enumerate(b):
            if y:
                out[i + j] = F.add(out[i + j], F.mul(x, y))
    return ptrim(out)


def pdivmod(F, a, b):
    a = list(a)
    b = ptrim(list(b))
    if not b:
        raise ZeroDivisionError
    db = len(b) - 1
    ilc = F.inv(b[-1])
    q = [0] * max(0, len(a) - db)
    while len(ptrim(a)) - 1 >= db and a:
        da = len(a) - 1
        c = F.mul(a[-1], ilc)
        q[da - db] = c
        for j in range(db + 1):
            a[da - db + j] = F.sub(a[da - db + j], F.mul(c, b[j]))
        ptrim(a)
    return ptrim(q), a


def pmonic(F, a):
    if not a:
        return a
    return pscale(F, a, F.inv(a[-1]))


def pgcd(F, a, b):
    a, b = ptrim(list(a)), ptrim(list(b))
    while b:
        _, r = pdivmod(F, a, b)
        a, b = b, r
    return pmonic(F, a)


def ppowmod_x(F, e, m):
    """x^e mod m"""
    result = [1]
    base = pdivmod(F, [0, 1], m)[1]
    while e:
        if e & 1:
            result = pdivmod(F, pmul(F, result, base), m)[1]
        base = pdivmod(F, pmul(F, base, base), m)[1]
        e >>= 1
    return result


def peval(F, a, x):
    r = 0
    for c in reversed(a):
        r = F.add(F.mul(r, x), c)
    return r


def splits_completely(F, poly):
    """True iff the nonzero poly is a product of linear factors over F_Q
    (a nonzero constant counts as split).  None for the zero polynomial."""
    g = ptrim(list(poly))
    if not g:
        return None
    while len(g) > 1:
        xq = ppowmod_x(F, F.Q, g)
        h = pgcd(F, g, psub(F, xq, [0, 1]))
        if len(h) <= 1:
            return False
        g, r = pdivmod(F, g, h)
        assert not r
    return True


def root_multiplicity(F, poly, r):
    g = ptrim(list(poly))
    m = 0
    lin = [F.neg(r), 1]
    while g:
        q, rem = pdivmod(F, g, lin)
        if rem:
            break
        m += 1
        g = q
    return m


def det(F, M):
    M = [row[:] for row in M]
    n = len(M)
    d = 1
    for c in range(n):
        piv = None
        for r in range(c, n):
            if M[r][c]:
                piv = r
                break
        if piv is None:
            return 0
        if piv != c:
            M[c], M[piv] = M[piv], M[c]
            d = F.neg(d)
        d = F.mul(d, M[c][c])
        ip = F.inv(M[c][c])
        for r in range(c + 1, n):
            if M[r][c]:
                fct = F.mul(M[r][c], ip)
                for j in range(c, n):
                    M[r][j] = F.sub(M[r][j], F.mul(fct, M[c][j]))
    return d


def sylvester_det(F, A, B, dA, dB):
    """Res_X of A (formal degree dA) and B (formal degree dB), numeric
    coefficient lists low -> high padded to formal length."""
    A = list(A) + [0] * (dA + 1 - len(A))
    B = list(B) + [0] * (dB + 1 - len(B))
    size = dA + dB
    M = []
    for i in range(dB):
        row = [0] * size
        for j in range(dA + 1):
            row[i + j] = A[dA - j]
        M.append(row)
    for i in range(dA):
        row = [0] * size
        for j in range(dB + 1):
            row[i + j] = B[dB - j]
        M.append(row)
    return det(F, M)


def interpolate(F, xs, ys):
    """coefficients (low -> high) of the poly of degree < len(xs) through pts"""
    n = len(xs)
    coef = list(ys)
    for j in range(1, n):
        for i in range(n - 1, j - 1, -1):
            coef[i] = F.div(F.sub(coef[i], coef[i - 1]), F.sub(xs[i], xs[i - j]))
    # Newton form -> monomial
    out = [0]
    for i in range(n - 1, -1, -1):
        out = padd(F, pmul(F, out, [F.neg(xs[i]), 1]), [coef[i]])
    return out


# ---------------------------------------------------------------- Semaev

def S3_value(F, a, b, x1, x2, x3):
    """S_3(x1,x2,x3) = (x1-x2)^2 x3^2 - 2((x1+x2)(x1 x2 + a) + 2b) x3
                        + (x1 x2 - a)^2 - 4 b (x1 + x2)"""
    d = F.sub(x1, x2)
    s = F.add(x1, x2)
    pr = F.mul(x1, x2)
    t2 = F.mul(F.mul(d, d), F.mul(x3, x3))
    t1 = F.mul(F.c(2), F.add(F.mul(s, F.add(pr, a)), F.mul(F.c(2), b)))
    t1 = F.mul(t1, x3)
    pa = F.sub(pr, a)
    t0 = F.sub(F.mul(pa, pa), F.mul(F.c(4), F.mul(b, s)))
    return F.add(F.sub(t2, t1), t0)


def S3_in_last(F, a, b, x1, x2):
    """coefficients in X of S_3(x1, x2, X), formal degree 2"""
    d = F.sub(x1, x2)
    s = F.add(x1, x2)
    pr = F.mul(x1, x2)
    c2 = F.mul(d, d)
    c1 = F.neg(F.mul(F.c(2), F.add(F.mul(s, F.add(pr, a)), F.mul(F.c(2), b))))
    pa = F.sub(pr, a)
    c0 = F.sub(F.mul(pa, pa), F.mul(F.c(4), F.mul(b, s)))
    return [c0, c1, c2]


def fibre(F, a, b, xs, method="interp"):
    """Formal-degree coefficient list (length 2^{n-1}+1) of
    S_{n+1}(x_1..x_n, T) built by Semaev's resultant recursion
      S_{m}(x_1..x_{m-1}, T) = Res_X( S_{m-1}(x_1..x_{m-2}, X), S_3(x_{m-1}, T, X) ).
    n = 1: S_2(x1, T) = x1 - T."""
    n = len(xs)
    if n == 1:
        return [xs[0], F.neg(1)]
    if n == 2:
        return S3_in_last(F, a, b, xs[0], xs[1])
    A = fibre(F, a, b, xs[:-1], method)          # in X, formal degree 2^{n-2}
    dA = 2 ** (n - 2)
    x = xs[-1]
    if method == "closed" and n == 3:
        # Res of two quadratics: (A2B0-A0B2)^2 - (A2B1-A1B2)(A1B0-A0B1),
        # with B_i polynomials in T
        A0, A1, A2 = A
        # S_3(x, T, X) coefficients in X, each a polynomial in T
        B2 = pmul(F, [x, F.neg(1)], [x, F.neg(1)])                 # (x - T)^2
        # -2((x+T)(xT + a) + 2b)
        inner = padd(F, pmul(F, [x, 1], [a, x]), [F.mul(F.c(2), b)])
        B1 = pscale(F, inner, F.neg(F.c(2)))
        xa = [F.neg(a), x]                                          # xT - a
        B0 = psub(F, pmul(F, xa, xa), pscale(F, [x, 1], F.mul(F.c(4), b)))
        u = psub(F, pscale(F, B0, A2), pscale(F, B2, A0))
        v = psub(F, pscale(F, B1, A2), pscale(F, B2, A1))
        w = psub(F, pscale(F, B0, A1), pscale(F, B1, A0))
        r = psub(F, pmul(F, u, u), pmul(F, v, w))
        return r + [0] * (2 ** (n - 1) + 1 - len(r))
    # evaluation / interpolation in T
    deg = 2 * dA
    if F.Q - 1 < deg + 1:
        raise ValueError("field too small for interpolation")
    pts = [F.exp[i] for i in range(deg + 1)]  # distinct nonzero elements
    ys = []
    for t in pts:
        Bv = S3_in_last(F, a, b, x, t)
        ys.append(sylvester_det(F, A, Bv, dA, 2))
    r = interpolate(F, pts, ys)
    return r + [0] * (deg + 1 - len(r))


# ---------------------------------------------------------------- curves

class Curve:
    def __init__(self, F, a, b):
        self.F, self.a, self.b = F, a, b
        disc = F.add(F.mul(F.c(4), F.pw(a, 3)), F.mul(F.c(27), F.mul(b, b)))
        if disc == 0:
            raise ValueError("singular")
        self._pts = None

    def f(self, x):
        F = self.F
        return F.add(F.add(F.pw(x, 3), F.mul(self.a, x)), self.b)

    def points(self):
        """affine points, then None for O"""
        if self._pts is None:
            F = self.F
            pts = []
            for x in F.elements():
                fx = self.f(x)
                c = F.chi(fx)
                if c == 0:
                    pts.append((x, 0))
                elif c == 1:
                    y = F.sqrt(fx)
                    y2 = F.neg(y)
                    pts.append((x, min(y, y2)))
                    pts.append((x, max(y, y2)))
            pts.append(None)
            self._pts = pts
        return self._pts

    def order(self):
        return len(self.points())

    def neg(self, P):
        if P is None:
            return None
        return (P[0], self.F.neg(P[1]))

    def add(self, P, R):
        F = self.F
        if P is None:
            return R
        if R is None:
            return P
        x1, y1 = P
        x2, y2 = R
        if x1 == x2:
            if F.add(y1, y2) == 0:
                return None
            lam = F.div(F.add(F.mul(F.c(3), F.mul(x1, x1)), self.a),
                        F.mul(F.c(2), y1))
        else:
            lam = F.div(F.sub(y2, y1), F.sub(x2, x1))
        x3 = F.sub(F.sub(F.mul(lam, lam), x1), x2)
        y3 = F.sub(F.mul(lam, F.sub(x1, x3)), y1)
        return (x3, y3)

    def mul(self, k, P):
        R = None
        if k < 0:
            k, P = -k, self.neg(P)
        while k:
            if k & 1:
                R = self.add(R, P)
            P = self.add(P, P)
            k >>= 1
        return R

    def group_table(self):
        """index map and addition table (lists) for the full group"""
        pts = self.points()
        idx = {P: i for i, P in enumerate(pts)}
        N = len(pts)
        add = [[0] * N for _ in range(N)]
        for i in range(N):
            for j in range(i, N):
                s = idx[self.add(pts[i], pts[j])]
                add[i][j] = s
                add[j][i] = s
        neg = [idx[self.neg(P)] for P in pts]
        return pts, idx, add, neg


def find_curve(F, rng, want_root_in_subfield=False, sub_p=None,
               coeffs_in_subfield=False, avoid_subfield=False):
    """random nonsingular y^2 = x^3 + a x + b over F"""
    while True:
        if coeffs_in_subfield:
            a = rng.randrange(sub_p)
            b = rng.randrange(sub_p)
        else:
            a = F.rand(rng)
            b = F.rand(rng)
        if avoid_subfield and (a < sub_p and b < sub_p):
            continue
        if want_root_in_subfield:
            x0 = rng.randrange(sub_p)
            b = F.neg(F.add(F.pw(x0, 3), F.mul(a, x0)))
            if avoid_subfield and (a < sub_p and b < sub_p):
                continue
        try:
            return Curve(F, a, b)
        except ValueError:
            continue


# ---------------------------------------------------------------- abstract groups

class AbGroup:
    """Z/n1 x Z/n2 x ... ; element index = mixed radix"""

    def __init__(self, mods):
        self.mods = list(mods)
        self.N = 1
        for m in mods:
            self.N *= m

    def dec(self, i):
        out = []
        for m in self.mods:
            i, r = divmod(i, m)
            out.append(r)
        return out

    def enc(self, v):
        i = 0
        for m, r in zip(reversed(self.mods), reversed(v)):
            i = i * m + (r % m)
        return i

    def tables(self):
        N = self.N
        vs = [self.dec(i) for i in range(N)]
        add = [[self.enc([x + y for x, y in zip(vs[i], vs[j])]) for j in range(N)]
               for i in range(N)]
        neg = [self.enc([-x for x in vs[i]]) for i in range(N)]
        return add, neg

