"""t0_selftest: library self-checks (fields, group law, S_3 vs group law,
S_4 by resultant two ways, S_5 roots)."""
import random, sys, json
sys.path.insert(0, __file__.rsplit('/', 1)[0])
from rd_lib import *

rng = random.Random(20261029)
out = {}

# fields
for (p, k) in [(5, 1), (31, 1), (101, 1), (5, 2), (7, 2), (11, 2), (31, 2), (5, 3), (7, 3)]:
    F = Field(p, k)
    bad = 0
    for _ in range(3000):
        x, y, z = F.rand(rng), F.rand(rng), F.rand(rng)
        if F.mul(x, F.add(y, z)) != F.add(F.mul(x, y), F.mul(x, z)):
            bad += 1
        if F.add(F.add(x, y), z) != F.add(x, F.add(y, z)):
            bad += 1
        if F.sub(F.add(x, y), y) != x:
            bad += 1
        if x and F.mul(x, F.inv(x)) != 1:
            bad += 1
        # digit-wise addition agrees
        if k > 1:
            dx, dy = F._dec(x), F._dec(y)
            if F._enc([(u + v) % p for u, v in zip(dx, dy)]) != F.add(x, y):
                bad += 1
        # Frobenius fixes exactly the prime field
        if (F.frob(x) == x) != (x < p):
            bad += 1
    nsq = sum(1 for x in range(1, F.Q) if F.chi(x) == 1)
    out[f"field_{p}^{k}"] = {"Q": F.Q, "modpoly": F.modpoly, "axiom_failures": bad,
                             "nonzero_squares": nsq, "expected": (F.Q - 1) // 2}

# curves, group law, S_3, S_4, S_5
res = []
for (p, k, n_tests) in [(31, 1, 400), (101, 1, 400), (7, 2, 300), (11, 2, 300), (5, 3, 300)]:
    F = Field(p, k)
    E = find_curve(F, rng)
    pts = E.points()
    N = len(pts)
    aff = pts[:-1]
    bad_assoc = bad_ord = bad_s3 = bad_s3sym = bad_s4 = bad_s4agree = bad_s5 = 0
    for _ in range(n_tests):
        P, R, S = rng.choice(aff), rng.choice(aff), rng.choice(aff)
        if E.add(E.add(P, R), S) != E.add(P, E.add(R, S)):
            bad_assoc += 1
        if E.mul(N, P) is not None:
            bad_ord += 1
        for T in (E.add(P, R), E.add(P, E.neg(R))):
            if T is not None and S3_value(F, E.a, E.b, P[0], R[0], T[0]) != 0:
                bad_s3 += 1
        x1, x2, x3 = F.rand(rng), F.rand(rng), F.rand(rng)
        v = S3_value(F, E.a, E.b, x1, x2, x3)
        for perm in [(x2, x1, x3), (x3, x2, x1), (x1, x3, x2)]:
            if S3_value(F, E.a, E.b, *perm) != v:
                bad_s3sym += 1
        # S_4 fibre by resultant, two independent evaluations
        xs = [P[0], R[0], S[0]]
        f_int = fibre(F, E.a, E.b, xs, "interp")
        f_cl = fibre(F, E.a, E.b, xs, "closed")
        if ptrim(list(f_int)) != ptrim(list(f_cl)):
            bad_s4agree += 1
        for e2 in (1, -1):
            for e3 in (1, -1):
                T = E.add(E.add(P, R if e2 == 1 else E.neg(R)), S if e3 == 1 else E.neg(S))
                if T is not None and peval(F, f_int, T[0]) != 0:
                    bad_s4 += 1
        if F.Q > 10 and _ % 3 == 0:
            U = rng.choice(aff)
            f5 = fibre(F, E.a, E.b, xs + [U[0]], "interp")
            for signs in itertools.product((1, -1), repeat=3):
                T = P
                for s_, Pt in zip(signs, (R, S, U)):
                    T = E.add(T, Pt if s_ == 1 else E.neg(Pt))
                if T is not None and peval(F, f5, T[0]) != 0:
                    bad_s5 += 1
    res.append({"p": p, "k": k, "a": E.a, "b": E.b, "N": N, "tests": n_tests,
                "assoc_fail": bad_assoc, "order_fail": bad_ord,
                "S3_vanish_fail": bad_s3, "S3_symmetry_fail": bad_s3sym,
                "S4_root_fail": bad_s4, "S4_interp_vs_closed_disagree": bad_s4agree,
                "S5_root_fail": bad_s5})
out["curves"] = res
print(json.dumps(out, indent=1))
